head.script:
scwin.onpageload = function() {

};
scwin.trigger1_onclick = function (e) {
    tac_test.setTabHTML("tabs1", "TEST_" + WebSquare.date.getCurrentServerDate("HH:mm:ss.SSS"));
	window.checkDate = WebSquare.date.getCurrentServerDate("HH:mm");
};

scwin.mpd_test_onprogress = function (data) {
    scwin.log("onprogress", data);
};

	scwin.checkVal = function() {
		const checkVal = WebSquare.wUnit.getDomById('tac_test_tab_tabs1_tabHTML').innerText;
		return checkVal.indexOf(window.checkDate) != -1;
	}
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()","true");
		WebSquare.wUnit.addCommand("pause", "500");	

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
